 * `vi.resetModules()`, every client that was opened during testing has to be
 * closed first. We therefore track each client that `getDb()` creates in a
 * process-global registry so it can be closed later.
 */

/** Minimal client shape needed to close a registered connection. */
type CloseableClient = {
  close: () => unknown;
  execute: (sql: string) => Promise<unknown>;
};

/** Client shape used for schema resets; `execute` reports rows from a query. */
type ResettableClient = {
  close: () => unknown;
  execute: (sql: string) => Promise<{ rows: Array<{ type: string; name: string }> }>;
};

// Stored on globalThis so the registry survives module-cache resets: `getDb()`
// registers a client, tests reset modules, and `closeTestDatabaseClients()` can
// still reach any client that was opened before the reset.
const REGISTRY_KEY = Symbol.for('promptfoo.testDatabaseClients');

function getRegistry(): Set<CloseableClient> {
  const globalWithRegistry = globalThis as typeof globalThis & {
    [REGISTRY_KEY]?: Set<CloseableClient>;
  };
  if (!globalWithRegistry[REGISTRY_KEY]) {
    globalWithRegistry[REGISTRY_KEY] = new Set<CloseableClient>();
  }
  return globalWithRegistry[REGISTRY_KEY];
}

/**
 * Register a database client so {@link closeTestDatabaseClients} can close it.
 * Called from `getDb()` in `src/database/index.ts` when `IS_TESTING` is set.
 */
export function registerTestDatabaseClient(client: CloseableClient): void {
  getRegistry().add(client);
}

/**
 * Close every client registered during testing and clear the registry. After
 * this resolves the registry is empty; combined with a module-cache reset, the
 * next `getDb()` opens a brand-new, isolated in-memory database.
 */
export async function closeTestDatabaseClients(): Promise<void> {
  const registry = getRegistry();
  for (const client of registry) {
    try {
      // libsql's close() is synchronous, but awaiting tolerates async clients too.
      await client.close();
    } catch (err) {
      logger.debug(`Error closing test database client: ${err}`);
    }
  }
  registry.clear();
}

/** Escape a SQL identifier: wrap in double quotes and double any internal quotes. */
function escapeIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/**
 * Drop all user-created tables, views, and triggers from a client's schema so
 * the database can be reused with a clean slate. Indexes are intentionally left
 * alone. The final statement executed is always `PRAGMA foreign_keys = ON`, even
 * if dropping an object fails.
 */
export async function resetTestDatabaseClient(client: ResettableClient): Promise<void> {
  try {
    // Fetch every user-created schema object; `sqlite_%` names are internal.
    const result = await client.execute(
      "SELECT type, name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'",
    );

    for (const { type, name } of result.rows) {
      let statement: string | null = null;
      const identifier = escapeIdentifier(name);
      if (type === 'table') {
        statement = `DROP TABLE IF EXISTS ${identifier}`;
      } else if (type === 'view') {
        statement = `DROP VIEW IF EXISTS ${identifier}`;
      } else if (type === 'trigger') {
        statement = `DROP TRIGGER IF EXISTS ${identifier}`;
      }
      // Indexes (and any other object types) are skipped: no DROP is issued.

      if (statement) {
        try {
          await client.execute(statement);
        } catch (err) {
          logger.debug(`Error dropping schema object ${name}: ${err}`);
        }
      }
    }
  } finally {
    // Restore the default pragma last, no matter what happened above.
    await client.execute('PRAGMA foreign_keys = ON');
  }
}
